-- Proposal rows are written only by the backend (postgres role, which bypasses RLS).
CREATE TABLE IF NOT EXISTS "public"."chat_proposals" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "thread_id"   bigint                   NOT NULL,
  "user_id"     bigint                   NOT NULL,
  "message_id"  bigint                   NOT NULL,
  "kind"        text                     NOT NULL,
  "title"       text                     NOT NULL,
  "when_label"  text                     NOT NULL,
  "why"         text                     NOT NULL,
  "payload"     jsonb                    NOT NULL,
  "status"      text                     NOT NULL DEFAULT 'pending',
  "created_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "chat_proposals_pkey" PRIMARY KEY (id),
  CONSTRAINT "chat_proposals_thread_id_fkey" FOREIGN KEY (thread_id) REFERENCES public.chat_threads(id) ON DELETE CASCADE,
  CONSTRAINT "chat_proposals_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE,
  CONSTRAINT "chat_proposals_message_id_fkey" FOREIGN KEY (message_id) REFERENCES public.chat_messages(id) ON DELETE CASCADE,
  CONSTRAINT "chat_proposals_kind_check" CHECK ((kind = ANY (ARRAY['task'::text, 'challenge'::text]))),
  CONSTRAINT "chat_proposals_status_check" CHECK ((status = ANY (ARRAY['pending'::text, 'created'::text, 'discarded'::text])))
);

CREATE INDEX IF NOT EXISTS "chat_proposals_message_id_idx"
  ON "public"."chat_proposals" (message_id);

CREATE INDEX IF NOT EXISTS "chat_proposals_thread_id_idx"
  ON "public"."chat_proposals" (thread_id);

ALTER TABLE "public"."chat_proposals" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Ver mis propias propuestas" ON "public"."chat_proposals"
  FOR SELECT
  TO "authenticated"
  USING ((user_id = public.get_current_user_id()));
